'use strict';

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert/strict');

// Given

Given('the app is open with no stored todos', async function () {
	await this.openApp({}, '');
});

Given('the app is open with an active todo {string} and a completed todo {string}', async function (activeTitle, completedTitle) {
	await this.openApp({}, '');
	this.addTodo(activeTitle, false);
	this.addTodo(completedTitle, true);
});

Given('the todo list contains an active todo {string}', function (title) {
	this.addTodo(title, false);
});

Given('the todo list contains a completed todo {string}', function (title) {
	this.addTodo(title, true);
});

Given('the todo list contains active todos {string} and {string}', function (first, second) {
	this.addTodo(first, false);
	this.addTodo(second, false);
});

Given('the todo list contains completed todos {string} and {string}', function (first, second) {
	this.addTodo(first, true);
	this.addTodo(second, true);
});

Given('the visitor has added an active todo {string}', function (title) {
	this.addTodo(title, false);
});

Given('the visitor has added a completed todo {string}', function (title) {
	this.addTodo(title, true);
});

Given('the visitor is on the {string} route', function (hash) {
	this.openRoute(hash);
});

Given('the visitor notes the row for {string}', function (title) {
	this.notedRow = this.findItem(title);
	assert.ok(this.notedRow, 'expected a todo titled ' + title);
});

// When

When('the visitor submits a new todo {string}', function (title) {
	this.submitNewTodo(title);
});

When('the visitor completes {string}', function (title) {
	this.toggleTodo(title);
});

When('the visitor reactivates {string}', function (title) {
	this.toggleTodo(title);
});

When('the visitor marks all todos as complete', function () {
	this.document.querySelector('.toggle-all').click();
});

When('the visitor starts editing {string}', function (title) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	li.querySelector('.view label').dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
	assert.ok(li.classList.contains('editing'), 'expected editing mode for ' + title);
});

When('the visitor changes the edit text to {string}', function (text) {
	const edit = this.document.querySelector('.todo-list li.editing .edit');
	assert.ok(edit, 'expected an open edit field');
	edit.value = text;
});

When('the edit field loses focus', function () {
	const edit = this.document.querySelector('.todo-list li.editing .edit');
	assert.ok(edit, 'expected an open edit field');
	edit.dispatchEvent(new this.window.Event('blur', { bubbles: false }));
});

When('the visitor presses Escape', function () {
	const edit = this.document.querySelector('.todo-list li.editing .edit');
	assert.ok(edit, 'expected an open edit field');
	edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
});

When('the visitor edits {string} to {string}', function (title, text) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	li.querySelector('.view label').dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
	assert.ok(li.classList.contains('editing'), 'expected editing mode for ' + title);
	const edit = li.querySelector('.edit');
	edit.value = text;
	edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When('the visitor destroys {string}', function (title) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	li.querySelector('.destroy').click();
});

When('the visitor clears completed todos', function () {
	this.document.querySelector('.clear-completed').click();
});

When('the visitor reloads the app', async function () {
	await this.reloadApp();
});

When('the visitor opens the {string} route', function (hash) {
	this.openRoute(hash);
});

// Then

Then('the todo list section is hidden', function () {
	assert.ok(this.isHidden(this.document.querySelector('.main')), 'expected the list section to be hidden');
});

Then('the footer is hidden', function () {
	assert.ok(this.isHidden(this.document.querySelector('.footer')), 'expected the footer to be hidden');
});

Then('the todo list contains {string}', function (title) {
	assert.ok(this.visibleTitles().includes(title), 'expected the todo list to contain ' + JSON.stringify(title) + ', saw ' + JSON.stringify(this.visibleTitles()));
});

Then('the todo list does not contain {string}', function (title) {
	assert.ok(!this.visibleTitles().includes(title), 'expected the todo list not to contain ' + JSON.stringify(title));
});

Then('the todo list is empty', function () {
	assert.equal(this.visibleTitles().length, 0, 'expected an empty todo list, saw ' + JSON.stringify(this.visibleTitles()));
});

Then('the new todo input is empty', function () {
	assert.equal(this.document.querySelector('.new-todo').value, '');
});

Then('the counter reads {string}', function (expected) {
	const text = this.document.querySelector('.todo-count').textContent.replace(/\s+/g, ' ').trim();
	assert.equal(text, expected);
});

Then('{string} is marked completed', function (title) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	assert.ok(li.classList.contains('completed'), 'expected ' + title + ' to be completed');
	assert.equal(li.querySelector('.toggle').checked, true);
});

Then('{string} is marked active', function (title) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	assert.ok(!li.classList.contains('completed'), 'expected ' + title + ' to be active');
});

Then('{string} is not in editing mode', function (title) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	assert.ok(!li.classList.contains('editing'), 'expected ' + title + ' not to be editing');
});

Then('the mark-all control is checked', function () {
	assert.equal(this.document.querySelector('.toggle-all').checked, true);
});

Then('the mark-all control is unchecked', function () {
	assert.equal(this.document.querySelector('.toggle-all').checked, false);
});

Then('the clear completed control is hidden', function () {
	assert.ok(this.isHidden(this.document.querySelector('.clear-completed')), 'expected clear completed to be hidden');
});

Then('localStorage key {string} holds a todo with the title {string}', function (key, title) {
	const raw = this.window.localStorage.getItem(key);
	assert.ok(raw, 'expected localStorage key ' + key);
	this.storedTodos = JSON.parse(raw);
	assert.ok(Array.isArray(this.storedTodos), 'expected a JSON array under ' + key);
	this.storedTodo = this.storedTodos.find((todo) => todo.title === title);
	assert.ok(this.storedTodo, 'expected a stored todo titled ' + JSON.stringify(title));
});

Then('that stored todo has an id field', function () {
	assert.ok(this.storedTodo && 'id' in this.storedTodo, 'expected an id field');
});

Then('that stored todo has a completed field set to false', function () {
	assert.equal(this.storedTodo && this.storedTodo.completed, false);
});

Then('the row for {string} is the same row element the visitor noted', function (title) {
	assert.ok(this.notedRow, 'expected a noted row');
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	assert.ok(li === this.notedRow, 'expected the row for ' + title + ' to be updated in place, not rebuilt');
});

Then('the toggle control for {string} is hidden', function (title) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	const toggle = li.querySelector('.toggle');
	assert.equal(this.window.getComputedStyle(toggle).display, 'none', 'expected the toggle for ' + title + ' to be hidden');
});

Then('the destroy control for {string} is hidden', function (title) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	const destroy = li.querySelector('.destroy');
	assert.equal(this.window.getComputedStyle(destroy).display, 'none', 'expected the destroy control for ' + title + ' to be hidden');
});

Then('the label for {string} is hidden', function (title) {
	const li = this.findItem(title);
	assert.ok(li, 'expected a todo titled ' + title);
	const label = li.querySelector('.view label');
	assert.equal(this.window.getComputedStyle(label).display, 'none', 'expected the label for ' + title + ' to be hidden');
});

Then('the {string} filter link is selected', function (label) {
	const links = [...this.document.querySelectorAll('.filters a')];
	const link = links.find((a) => a.textContent.trim() === label);
	assert.ok(link, 'expected a filter link labelled ' + label);
	assert.ok(link.classList.contains('selected'), 'expected the ' + label + ' filter link to be selected');
});

'use strict';

const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..', '..');

class TodoWorld extends World {
	async openApp(storage, hash) {
		this.window = new Window({ url: 'http://localhost/' + (hash || '') });
		const html = fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8');
		this.window.document.write(html);
		this.document = this.window.document;
		try {
			const css = fs.readFileSync(path.join(ROOT, 'css', 'app.css'), 'utf8');
			const style = this.document.createElement('style');
			style.textContent = css;
			this.document.head.appendChild(style);
		} catch (error) {
			// css/app.css not present
		}
		if (storage) {
			for (const key of Object.keys(storage)) {
				this.window.localStorage.setItem(key, storage[key]);
			}
		}
		const appSource = fs.readFileSync(path.join(ROOT, 'js', 'app.js'), 'utf8');
		const run = new Function('window', 'document', 'localStorage', 'location', appSource);
		run(this.window, this.document, this.window.localStorage, this.window.location);
	}

	async reloadApp() {
		const storage = {};
		for (let i = 0; i < this.window.localStorage.length; i++) {
			const key = this.window.localStorage.key(i);
			storage[key] = this.window.localStorage.getItem(key);
		}
		const hash = this.window.location.hash;
		await this.openApp(storage, hash);
	}

	// Actor helpers, shared by Given and When steps.

	submitNewTodo(title) {
		const input = this.document.querySelector('.new-todo');
		input.value = title;
		input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
	}

	addTodo(title, completed) {
		this.submitNewTodo(title);
		if (completed) {
			this.toggleTodo(title);
		}
	}

	findItem(title) {
		const items = [...this.document.querySelectorAll('.todo-list li')];
		return items.find((li) => li.querySelector('.view label').textContent === title) || null;
	}

	toggleTodo(title) {
		const li = this.findItem(title);
		if (!li) {
			throw new Error('no todo titled ' + JSON.stringify(title));
		}
		li.querySelector('.toggle').click();
	}

	openRoute(hash) {
		this.window.location.hash = hash;
		this.window.dispatchEvent(new this.window.Event('hashchange'));
	}

	visibleTitles() {
		return [...this.document.querySelectorAll('.todo-list li')]
			.map((li) => li.querySelector('.view label').textContent);
	}

	isHidden(el) {
		return el.hidden || el.style.display === 'none';
	}
}

setWorldConstructor(TodoWorld);

